<script setup lang="ts">
import {tr} from '../lib/i18n'
import { computed, onUnmounted, ref } from 'vue'
import { ApiError, post } from '../lib/api'
import PageTransition from './PageTransition.vue'
const props = defineProps<{initial: string}>()
const emit = defineEmits<{back: []; authenticated: [token:string]}>()
const target = ref(props.initial === 'create' ? 'signup' : props.initial === 'apple' ? 'apple' : 'signin')
const route = new URLSearchParams(location.search).get('auth')
const mode = ref(['terms','privacy'].includes(props.initial) ? props.initial : 'consent')
if (route && ['signin','signup','forgot','verify','recovery','password','apple','privacy','consent'].includes(route)) mode.value = route === 'recovery' ? 'verify' : route
const accepted = ref(false), email = ref(new URLSearchParams(location.search).get('email') || ''), name = ref(''), password = ref(''), confirm = ref(''), code = ref(''), show = ref(false), share = ref(false)
const error = ref(''), notice = ref(''), busy = ref(false), recovery = ref(route === 'recovery'), token = ref(''), seconds = ref(0)
let deadline = 0
const timer = window.setInterval(() => { seconds.value = Math.max(0, Math.ceil((deadline - Date.now()) / 1000)) }, 250)
onUnmounted(() => clearInterval(timer))
const title = computed(() => ({consent:'Before you continue',signin:'Welcome back',signup:'Create your account',forgot:'Forgot your password?',verify:recovery.value?'Password recovery':'Verify your email',password:'Choose a new password',apple:'Apple sign-in',privacy:'Privacy information',terms:'Terms of Use & EULA',session:'Welcome to MauGo'}[mode.value]))
function go(next: string) { mode.value = next; error.value = ''; notice.value = ''; password.value = ''; confirm.value = ''; code.value = '' }
function back() { if(mode.value === 'privacy' || mode.value === 'terms') go(accepted.value ? target.value : 'consent'); else emit('back') }
function validEmail() { if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.value.trim())) {error.value='Enter a valid email address.';return false} return true }
async function request(work: () => Promise<void>) { if(busy.value)return; busy.value=true;error.value='';notice.value='';try {await work()} catch(e) {
 const err=e as ApiError
 if(err.retryAfter) {deadline=Date.now()+err.retryAfter*1000;seconds.value=err.retryAfter}
 error.value=err.status===503 && /SMTP/i.test(err.message)?'Email delivery is unavailable. Please try again later.':err.status===401&&mode.value==='verify'?'Incorrect verification code. Please try again.':err.status===410?'Verification code expired. Please request a new code.':err.message || 'Cannot connect to the server. Please try again later.'
 } finally {busy.value=false} }
async function sendCode() { if(!validEmail())return; await request(async()=> {const r=await post<{sent:boolean;retryAfter:number}>('/auth/code/send',{email:email.value.trim()});if(r.sent){deadline=Date.now()+60000;seconds.value=60;notice.value='Verification email sent.'}}) }
async function submit() {
 error.value=''
 if(mode.value!=='password'&&!validEmail())return
 if(mode.value==='forgot') {recovery.value=true;go('verify');await sendCode();return}
 if(mode.value==='signup'&&!name.value.trim()){error.value='Enter a nickname.';return}
 if(password.value.length<8||password.value.length>128||!/[A-Za-z]/.test(password.value)||!/[0-9\W]/.test(password.value)){error.value='Use at least 8 characters, with a letter and a number or symbol.';return}
 if(['signup','password'].includes(mode.value)&&password.value!==confirm.value){error.value='Passwords do not match.';return}
 if(mode.value==='password'){error.value='Password reset is not connected yet. Your password has not been changed.';return}
 if(!accepted.value){target.value=mode.value;go('consent');return}
 await request(async()=>{const signup=mode.value==='signup';const r=await post<{token:string}>('/auth/'+(signup?'signup':'login'),{email:email.value.trim(),password:password.value,...(signup?{confirmPassword:confirm.value}:{}),termsVersion:'1.0',privacyVersion:'1.0'});token.value=r.token;password.value='';confirm.value='';if(signup){recovery.value=false;go('verify');}else go('session')})
 if(mode.value==='verify')await sendCode()
}
async function verify() {error.value='';if(!/^\d{6}$/.test(code.value)){error.value='Enter a 6-digit code.';return}if(!validEmail())return;await request(async()=>{const r=await post<{verified:boolean}>('/auth/code/verify',{email:email.value.trim(),code:code.value});if(r.verified)go(recovery.value?'password':'session')})}
async function apple(cancelled=false) {await request(async()=>{const result=await post<{cancelled?:boolean}>('/auth/apple',cancelled?{cancelled:true}:{});if(result.cancelled)emit('back');else error.value='Apple sign-in did not complete. No session was issued.'})}
async function logout(){await request(async()=>{await post('/auth/logout',{},token.value);token.value='';emit('back')})}
</script>
<template>
<div class="auth-flow"><button class="text-button back" :aria-label="tr('Back')" @click="back">{{tr("‹ Back")}}</button>
<PageTransition><section :key="mode" class="flow-content"><h1>{{ tr(title) }}</h1>
<template v-if="['consent','terms','privacy'].includes(mode)"><p class="auth-copy">{{tr(mode==='privacy'?'How MauGo handles your information.':'Read the terms before registering or signing in.')}}</p><article v-if="mode!=='privacy'" class="terms-scroll terms-document" tabindex="0"><slot name="legal" /><article class="policy-copy terms-document" data-user-content><p class="terms-version">{{tr("Version 1.0 · 13 October 2026 · Review draft")}}</p><h2>{{tr("1. About this agreement")}}</h2><p>{{tr("MauGo provides a space to share letters, messages and moments. These Terms of Use and End User License Agreement govern your use of MauGo. You must be at least 18 and legally able to accept these terms. If you do not agree, do not register, sign in or use account features.")}}</p><h2>{{tr("2. Your account")}}</h2><p>{{tr("Use accurate information, keep your sign-in details secure and do not impersonate others or share access without permission. You are responsible for activity you authorize. Email and Apple are supported sign-in methods in the intended app; this preview only demonstrates their screens.")}}</p><h2>{{tr("3. Permission to use MauGo")}}</h2><p>{{tr("MauGo grants a personal, limited, non-exclusive and non-transferable license to use the app under these terms and applicable store rules. Do not resell, unlawfully copy, bypass security, disrupt the service or reverse engineer it except where law permits. MauGo retains rights in its app and brand.")}}</p><h2>{{tr("4. Content and respectful conduct")}}</h2><p>{{tr("MauGo has zero tolerance for objectionable content or abusive users. Do not post or send harassment, bullying, threats, hate speech, sexual exploitation, illegal sexual content, scams, spam, impersonation, or content that infringes rights. Do not publish private information without permission. These rules apply to letters, chats, profiles, images, recordings, stickers and moments.")}}</p><h2>{{tr("5. Your content and conversation rules")}}</h2><p>{{tr("You retain ownership of your content and must have permission to share it. You grant MauGo only the rights needed to store, display, transmit and moderate it for the service. One opening text message is permitted per new connection; further chat and attachments unlock after the recipient replies. Do not bypass this limit or repeatedly contact someone who declines or blocks you.")}}</p><h2>{{tr("6. Reporting, blocking and enforcement")}}</h2><p>{{tr("Use Report and Block in letter or conversation controls to flag unwanted content and stop contact. In the released service, MauGo may review reports, remove content and restrict or terminate abusive accounts, with notice and review where required by law. This preview saves reports locally; it has no connected moderation team and cannot deliver reports. It is not an emergency service.")}}</p><h2>{{tr("7. Diamonds and paid features")}}</h2><p>{{tr("In the intended app, diamonds are purchased in USD through the applicable store and used for features at the displayed price. Diamonds are not money, cannot be cashed out or transferred, and have no value outside MauGo. Filter Pass duration and diamond cost are shown before confirmation; extra days extend expiry and there is no automatic renewal. Store rules and mandatory consumer rights govern refunds. This preview uses test balances and makes no real charge.")}}</p><h2>{{tr("8. Privacy and permissions")}}</h2><p>{{tr("Read Privacy information to understand the current data use. This preview stores account personas, messages and preferences in browser storage and selected media in IndexedDB. It does not send authentication emails or store passwords. File access follows your selection; microphone permission is requested for recording. Clearing local browser data may remove content. Hosting providers may process access logs.")}}</p><h2>{{tr("9. Availability and your rights")}}</h2><p>{{tr("MauGo may change or discontinue features, subject to applicable law and purchased entitlements. You may stop using it and use account settings to export or delete local data. The preview is provided for evaluation without a promise of uninterrupted availability. Nothing in these terms excludes non-excludable warranties, liability or consumer rights under the laws that apply to you.")}}</p><h2>{{tr("10. Apple distribution")}}</h2><p>{{tr("For an app distributed by Apple, this agreement is between you and MauGo. Apple is not responsible for app support, app-related claims or intellectual-property disputes; MauGo is responsible as required by law. If the app fails an applicable warranty, Apple may refund its purchase price under its rules. Apple and its subsidiaries may enforce this agreement as third-party beneficiaries. Use Apple devices you own or control and follow store usage rules, including permitted family access. Comply with applicable export and sanctions restrictions.")}}</p><h2>{{tr("11. Updates and contact")}}</h2><p>{{tr("Material changes will be shown before requesting renewed agreement. Contact MauGo at maugo.support@example.com. This is a reserved example address for the design preview, not an active support inbox; replace it with the actual MauGo support address before release. Version 1.0 · 13 October 2026. This document is a review draft for the prototype and does not create a real service contract.")}}</p></article></article><p v-if="mode==='privacy'" class="privacy-copy">{{tr("Email and password are sent to the configured MauGo server for authentication. Passwords are never stored on this device. Session credentials stay in memory and are revoked when you sign out. Email verification requires a configured mail service. Apple authorization is not yet fully configured.")}}</p><template v-if="mode==='consent'"><label class="terms-check"><input id="accept-terms" v-model="accepted" type="checkbox"><span>{{tr("I have read and agree to the Terms of Use and EULA.")}}</span></label><button id="terms-continue" class="primary auth-main" :disabled="!accepted" @click="go(target)">{{tr("Agree & continue")}}</button><button class="auth-preview" @click="emit('back')">{{tr("Not now")}}</button><button class="auth-link" @click="go('privacy')">{{tr("Privacy information")}}</button></template></template>
<template v-else-if="['signin','signup','forgot','password'].includes(mode)"><p class="auth-copy">{{tr(mode==='signup'?'A kind space starts with a little hello.':mode==='forgot'?'Enter your email to recover your password.':mode==='password'?'Use a new password you have not used before.':'Your little corner is waiting for you.')}}</p><form id="auth-form" novalidate @submit.prevent="submit"><label v-if="mode==='signup'" class="field-label">{{tr("Nickname")}}<input id="auth-name" v-model="name" maxlength="24" autocomplete="nickname"></label><label v-if="mode!=='password'" class="field-label">{{tr("Email address")}}<input id="auth-email" v-model="email" type="email" inputmode="email" autocomplete="email" maxlength="254"></label><label v-if="mode!=='forgot'" class="field-label">{{tr(mode==='password'?'New password':'Password')}}<input id="auth-password" v-model="password" :type="show?'text':'password'" :autocomplete="mode==='signin'?'current-password':'new-password'" maxlength="128"></label><label v-if="['signup','password'].includes(mode)" class="field-label">{{tr("Confirm password")}}<input id="auth-confirm" v-model="confirm" :type="show?'text':'password'" autocomplete="new-password" maxlength="128"></label><label v-if="mode!=='forgot'" class="show-password"><input v-model="show" type="checkbox">{{tr("Show password")}}</label><p v-if="['signup','password'].includes(mode)" class="password-hint">{{tr("At least 8 characters, with a letter and a number or symbol.")}}</p><button v-if="mode==='signin'" type="button" class="auth-link" @click="go('forgot')">{{tr("Forgot password?")}}</button><button class="primary auth-main" :disabled="busy">{{tr(busy?'Please wait…':mode==='signup'?'Create account':mode==='forgot'?'Continue':mode==='password'?'Update password':'Sign in')}}</button></form><p v-if="['signin','signup'].includes(mode)" class="auth-switch">{{tr(mode==='signup'?'Already have an account?':'New here?')}} <button class="text-button" @click="go(mode==='signup'?'signin':'signup')">{{tr(mode==='signup'?'Sign in':'Create an account')}}</button></p><button v-else class="auth-preview" @click="go('signin')">{{tr("Back to sign in")}}</button></template>
<template v-else-if="mode==='verify'"><div class="mail-orbit">✉</div><p class="auth-copy">{{tr("Email verification for:")}}</p><p class="auth-address">{{email}}</p><form id="code-form" novalidate @submit.prevent="verify"><label class="field-label">{{tr("6-digit code")}}<input id="auth-code" v-model="code" inputmode="numeric" autocomplete="one-time-code" maxlength="6" pattern="[0-9]{6}" @input="code=code.replace(/\D/g,'')"></label><button class="primary auth-main" :disabled="busy">{{tr("Verify & continue")}}</button></form><button id="resend-email" class="auth-preview" :disabled="busy||seconds>0" @click="sendCode">{{tr("Resend code")}}{{tr(seconds>0?` (${seconds}s)`:'')}}</button><button class="auth-preview" @click="go(recovery?'forgot':'signup')">{{tr("Use a different email")}}</button><button v-if="token" class="auth-preview" @click="logout">{{tr("Sign out")}}</button></template>
<template v-else-if="mode==='apple'"><div class="apple-orbit">{{tr("Apple")}}</div><p class="auth-copy">{{tr("Apple sign-in requires native authorization and server configuration. The full flow is not connected yet.")}}</p><div class="language-options"><button id="apple-hide" :aria-pressed="!share" @click="share=false">{{tr("Hide my email")}} <b>{{tr(!share?'✓':'')}}</b></button><button id="apple-share" :aria-pressed="share" @click="share=true">{{tr("Share my email")}} <b>{{tr(share?'✓':'')}}</b></button></div><p class="auth-address">{{tr(share?'Share my email':'Hide my email')}} {{tr("· Awaiting Apple authorization")}}</p><button class="primary auth-main" :disabled="busy" @click="apple()">{{tr("Continue with Apple")}}</button><button class="auth-preview" :disabled="busy" @click="apple(true)">{{tr("Cancel")}}</button></template>
<template v-else-if="mode==='session'"><div class="mail-orbit">✦</div><p class="auth-copy">{{tr("You are signed in.")}}</p><p class="auth-address">{{email}}</p><button class="primary" @click="emit('authenticated',token)">{{tr("Meet your letters")}}</button><button class="primary" :disabled="busy" @click="logout">{{tr("Sign out")}}</button></template>
<p v-if="error" id="auth-error" class="auth-error" role="alert">{{tr(error)}}</p><p v-if="notice" role="status" class="auth-copy">{{tr(notice)}}</p>
</section></PageTransition></div>
</template>
